import{_ as a,a8 as e,o as s,c,ah as l,K as t}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const k=JSON.parse('{"title":"AI 项目目录迁移手册（WorkBuddy / Trae / ZCode 通用）","description":"","frontmatter":{"type":"workflow","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["迁移","WorkBuddy","Trae","ZCode","会话历史","改绑"]},"headers":[],"relativePath":"vault/Memory/Workflows/AI项目目录迁移手册.md","filePath":"vault/Memory/Workflows/AI项目目录迁移手册.md","lastUpdated":1789374053000}'),i={name:"vault/Memory/Workflows/AI项目目录迁移手册.md"};function n(g,o,h,p,u,_){const d=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return s(),c("div",null,[o[0]||(o[0]=l('<h1 id="ai-项目目录迁移手册-workbuddy-trae-zcode-通用" tabindex="-1">AI 项目目录迁移手册（WorkBuddy / Trae / ZCode 通用） <a class="header-anchor" href="#ai-项目目录迁移手册-workbuddy-trae-zcode-通用" aria-label="Permalink to “AI 项目目录迁移手册（WorkBuddy / Trae / ZCode 通用）”">​</a></h1><p>迁移 <code>E:\\&lt;源&gt;\\&lt;项目&gt;</code> → <code>E:\\Projects\\&lt;类&gt;\\&lt;英文名&gt;</code> 并保留全部 AI 会话历史的固定流程。</p><h2 id="标准步骤" tabindex="-1">标准步骤 <a class="header-anchor" href="#标准步骤" aria-label="Permalink to “标准步骤”">​</a></h2><ol><li><strong>归属确认</strong>：查各工具是否绑定该项目（WB：<code>~/.workbuddy/workbuddy.db</code> sessions/workspaces；Trae：<code>~/.trae-cn/memory/projects/</code> slug + SOLO <code>state.vscdb</code> content-map；ZCode：<code>~/.zcode/v2/tasks-index.sqlite</code>）</li><li><strong>备份</strong>：<code>E:\\Projects\\.migration-backups\\&lt;tag&gt;\\</code>（文件清单+MD5、各 state 库副本）</li><li><strong>复制</strong>：robocopy <code>/E /COPY:DAT</code>（长路径安全）→ 校验（数量+字节全比，MD5 小文件全查+大文件抽样或流式全比）</li><li><strong>删源</strong>：rmtree（加 <code>\\?\\</code> 前缀防长路径）；百度同步盘删源会同步删除云端</li><li><strong>改绑</strong>（各自关闭后）： <ul><li>WB：UPDATE sessions.cwd + workspaces.path</li><li>Trae：改 memory slug 目录名（<strong>按新路径命名，保留 p2 哈希后缀</strong>——记忆按路径挂载，改名即延续）；content-map 里的旧路径按<strong>原编码深度</strong>做字符串替换</li><li>ZCode：离线脚本（关 ZCode 后跑）改 tasks-index / setting.json / rollout / checkpoint，见 <code>E:\\Projects\\.migration-backups\baidu-20260912 ebind_wenzhuan.py</code>（支持 --root 测试参数，先沙盒干跑）</li></ul></li></ol><h2 id="关键坑" tabindex="-1">关键坑 <a class="header-anchor" href="#关键坑" aria-label="Permalink to “关键坑”">​</a></h2><ul><li><strong>ZCode 的 project_id 由路径推导生成</strong>：路径转小写、非 <code>[a-z0-9]</code> 字符替换为 <code>-</code>。迁移时新旧路径推导出的 id 必须一致，否则改绑后会话挂不回项目（2026-09-11 实测）</li><li><strong>改 SQLite 前必须让应用完全退出</strong>：未 checkpoint 的 WAL 会写入冲突/回滚。流程 <code>Get-Process 检查 → Stop-Process → 改库 → 重启对账</code></li><li><strong>路径替换至少要覆盖 4 种写法</strong>：<code>E:\\</code> / <code>e:\\</code> / <code>E:/</code> / <code>e:/</code>——同一库里大小写混用是常态，漏一种就会残留（实测 316 处替换后残留 0）</li><li><strong>WB 库里软删除会话仍指向旧路径属正常回收机制</strong>，不必强行清理；对账以有效会话数为准</li><li><strong>SOLO 项目→文件夹绑定存在云端</strong>（<code>lite list_projects</code> 每次启动覆盖本地 state.vscdb）——纯改本地库无效，用 junction 或让用户在 UI 重开目录</li><li>SOLO 真正的项目库 <code>ModularData\x07i-agent\\database.db</code> 是<strong>加密 SQLite</strong>，不可直接编辑</li><li>ZCode tasks-index 的 <code>-wal</code> 文件可能含未合并提交：只备份<strong>不删</strong>，先 <code>PRAGMA wal_checkpoint(TRUNCATE)</code> 再改</li><li>替换路径要覆盖<strong>所有编码深度</strong>（1/2/4 反斜杠、正斜杠、<code>/e:/</code>、<code>e%3A/</code>、百分号编码）与子目录形式</li><li>会话正文可能被工具自动清理（如 ZCode rollout 会消失），<strong>重要会话内容应整理成记忆文档落盘</strong>（参考各项目 <code>.memory/sessions-history.md</code>）</li></ul><h2 id="验收清单-迁移后对账-2026-09-11「虚拟商品」样例" tabindex="-1">验收清单（迁移后对账，2026-09-11「虚拟商品」样例） <a class="header-anchor" href="#验收清单-迁移后对账-2026-09-11「虚拟商品」样例" aria-label="Permalink to “验收清单（迁移后对账，2026-09-11「虚拟商品」样例）”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>判据</th><th>样例结果</th></tr></thead><tbody><tr><td>文件完整性</td><td>数量 + 字节全比；小文件 MD5 全查</td><td>11/11 MD5 一致</td></tr><tr><td>数据库改绑</td><td>受影响行数明确</td><td>更新 2 行</td></tr><tr><td>路径残留</td><td>全库搜旧路径</td><td>316 处替换，残留 0</td></tr><tr><td>会话加载</td><td>重启工具后完整可读</td><td>443 行会话加载正常</td></tr></tbody></table><ul><li>先拿一个小项目做<strong>测试迁移</strong>打通全流程，再批量推其余项目</li><li>迁移中若出现 Windows 保留设备名文件（如 <code>nul</code>）导致删源失败，用 <code>\\\\?\\</code> 扩展路径前缀绕过</li></ul>',9)),t(d),t(r)])}const y=a(i,[["render",n]]);export{k as __pageData,y as default};
